res = subprocess.run(["./executable", "bogus_command"], capture_output=True, text=True)
outputs["bogus_cmd"] = {"out": res.stdout, "err": res.stderr, "code": res.returncode}

with open("outputs.json", "w") as f:
    json.dump(outputs, f)
