{"command":"cat <<'EOF' > extract_flags.py
import json
import re

d = json.load(open('outputs.json'))
valid_flags = set()

for key, val in d.items():
    if key.endswith('_help') or key == 'global_help':
        out = val['out']
        # Find lines like "  -o, --connect-options value" or "      --debug"
        for line in out.split('\n'):
            line = line.strip()
            if line.startswith('-') and '--' in line:
                # Match "--flag-name"
                m = re.search(r'--([a-zA-Z0-9_-]+)', line)
                if m:
                    flag = m.group(1)
                    # Handle optional [skip-] prefix
                    if flag.startswith('[skip-]'):
                        base = flag[7:]
                        valid_flags.add(base)
                        valid_flags.add(f"skip-{base}")
                    else:
                        valid_flags.add(flag)
            elif line.startswith('--'):
                m = re.search(r'--([a-zA-Z0-9_-]+)', line)
                if m:
                    flag = m.group(1)
                    if flag.startswith('[skip-]'):
                        base = flag[7:]
                        valid_flags.add(base)
                        valid_flags.add(f"skip-{base}")
                    else:
                        valid_flags.add(flag)

print("Valid flags:", sorted(list(valid_flags)))
EOF
